#include <Arduino.h>

#define SENSOR1_PIN A0
#define SENSOR2_PIN A1
#define BUTTON_PIN  2
#define LED_PIN     13

#define MODE1 1
#define MODE2 2

#define SENSOR_THRESHOLD 500
#define NUM_FINGERS 5
#define ANGLE_MIN 0
#define ANGLE_MAX 100
#define INIT_DELAY 500
#define PAUSE_DURATION 5000
#define BUTTON_DEBOUNCE 50
#define SHORT_PRESS_MIN 300
#define SHORT_PRESS_MAX 500
#define LONG_PRESS_MIN 3000
#define DOUBLE_CLICK_INTERVAL 500
#define LED_FLASH_PERIOD 1000
#define LED_TWO_SHORT_ON 100
#define LED_TWO_SHORT_OFF 100

enum SystemState {
    STATE_INIT,
    STATE_PAUSE,
    STATE_ONE_SENSOR,
    STATE_MODE1,
    STATE_MODE2,
    STATE_EMERGENCY
};

enum GripType {
    GRIP_POWER,
    GRIP_CLOSED_PINCER,
    GRIP_OPEN_PINCER,
    GRIP_KEYBOARD,
    GRIP_CUP_HOLD
};

struct GripDefinition {
    GripType type;
    uint8_t targetAngles[NUM_FINGERS];
    bool hold;
    uint8_t speed;
};

SystemState currentState = STATE_INIT;
volatile int currentAngles[NUM_FINGERS] = {0,0,0,0,0};
volatile int targetAngles[NUM_FINGERS] = {0,0,0,0,0};
uint8_t currentSpeed = 100;

volatile bool buttonPressed = false;
volatile unsigned long buttonPressTime = 0;
volatile unsigned long buttonReleaseTime = 0;
volatile unsigned long lastSingleClickTime = 0;
volatile bool singleClickPending = false;
volatile bool doubleClickDetected = false;

unsigned long lastLEDToggleTime = 0;
bool ledState = false;
int ledFlashMode = 0;

GripType currentGrip = GRIP_POWER;
bool gripActive = false;
bool gripHoldActive = false;
uint8_t gripSpeed = 100;

bool sensor1Active = false;
bool sensor2Active = false;
bool prevSensor1Active = false;
bool prevSensor2Active = false;

unsigned long pauseStartTime = 0;
unsigned long emergencyStartTime = 0;
bool emergencyExitPending = false;

int initFingerIndex = 0;
bool initPhase = 0;

void setFinger(int finger, int angle, int speed);
void updateFingers();
void executeGrip(GripType grip, bool hold, uint8_t speed);
void releaseGrip();
void updateLED();
void handleButton();
void initSystem();
bool isSensorActive(int pin);
void processOneSensor();
void processTwoSensors(int mode);
void processEmergency();
void handleSingleClick();
void handleDoubleClick();
void enterEmergency();

const GripDefinition grips[] = {
    {GRIP_POWER, {100,100,100,100,100}, true, 90},
    {GRIP_CLOSED_PINCER, {100,100,100,100,100}, false, 70},
    {GRIP_OPEN_PINCER, {100,100,0,0,0}, true, 70},
    {GRIP_KEYBOARD, {100,0,100,100,100}, true, 70},
    {GRIP_CUP_HOLD, {100,100,100,100,100}, true, 50}
};

void setup() {
    Serial.begin(115200);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    pinMode(SENSOR1_PIN, INPUT);
    pinMode(SENSOR2_PIN, INPUT);

    currentState = STATE_INIT;
    for (int i = 0; i < NUM_FINGERS; i++) {
        currentAngles[i] = 0;
        targetAngles[i] = 0;
    }
    Serial.println("Система запущена. Инициализация...");
}

void loop() {
    updateFingers();
    handleButton();

    switch (currentState) {
        case STATE_INIT:
            initSystem();
            break;
        case STATE_PAUSE:
            if (millis() - pauseStartTime >= PAUSE_DURATION) {
                currentState = STATE_ONE_SENSOR;
                ledFlashMode = 3;
                lastLEDToggleTime = millis();
                Serial.println("Переход в режим ONE_SENSOR");
            }
            break;
        case STATE_ONE_SENSOR:
            processOneSensor();
            break;
        case STATE_MODE1:
            processTwoSensors(MODE1);
            break;
        case STATE_MODE2:
            processTwoSensors(MODE2);
            break;
        case STATE_EMERGENCY:
            processEmergency();
            break;
    }

    updateLED();
    delay(10);
}

void initSystem() {
    static bool initDone = false;
    if (!initDone) {
        if (initFingerIndex < NUM_FINGERS) {
            if (initPhase == 0) {
                setFinger(initFingerIndex, ANGLE_MAX, 50);
                delay(INIT_DELAY);
                initPhase = 1;
            } else {
                setFinger(initFingerIndex, ANGLE_MIN, 50);
                delay(INIT_DELAY);
                initFingerIndex++;
                initPhase = 0;
            }
        } else {
            initDone = true;
            currentState = STATE_PAUSE;
            pauseStartTime = millis();
            Serial.println("Инициализация завершена. Пауза 5 сек...");
        }
    }
}

void setFinger(int finger, int angle, int speed) {
    if (finger < 0 || finger >= NUM_FINGERS) return;
    targetAngles[finger] = constrain(angle, ANGLE_MIN, ANGLE_MAX);
    currentSpeed = speed;
}

void updateFingers() {
    for (int i = 0; i < NUM_FINGERS; i++) {
        if (currentAngles[i] != targetAngles[i]) {
            int diff = targetAngles[i] - currentAngles[i];
            int step = (diff > 0) ? max(1, (currentSpeed * diff) / 100) : min(-1, (currentSpeed * diff) / 100);
            currentAngles[i] += step;
            if ((diff > 0 && currentAngles[i] > targetAngles[i]) || (diff < 0 && currentAngles[i] < targetAngles[i])) {
                currentAngles[i] = targetAngles[i];
            }
        }
    }
}

void executeGrip(GripType grip, bool hold, uint8_t speed) {
    const GripDefinition* def = nullptr;
    switch (grip) {
        case GRIP_POWER: def = &grips[0]; break;
        case GRIP_CLOSED_PINCER: def = &grips[1]; break;
        case GRIP_OPEN_PINCER: def = &grips[2]; break;
        case GRIP_KEYBOARD: def = &grips[3]; break;
        case GRIP_CUP_HOLD: def = &grips[4]; break;
    }
    if (!def) return;
    for (int i = 0; i < NUM_FINGERS; i++) {
        setFinger(i, def->targetAngles[i], speed);
    }
    currentGrip = grip;
    gripHoldActive = hold;
    gripActive = true;
    Serial.print("Выполняется схват: ");
    Serial.println(grip);
}

void releaseGrip() {
    for (int i = 0; i < NUM_FINGERS; i++) {
        setFinger(i, ANGLE_MIN, 100);
    }
    gripActive = false;
    gripHoldActive = false;
    Serial.println("Схват отпущен");
}

void processOneSensor() {
    bool sensor = isSensorActive(SENSOR1_PIN);
    static bool prevSensor = false;
    static bool gripExecuted = false;

    if (sensor && !prevSensor) {
        if (!gripExecuted) {
            executeGrip(GRIP_POWER, true, 90);
            gripExecuted = true;
        } else {
            releaseGrip();
            gripExecuted = false;
        }
    }
    prevSensor = sensor;
}

void processTwoSensors(int mode) {
    sensor1Active = isSensorActive(SENSOR1_PIN);
    sensor2Active = isSensorActive(SENSOR2_PIN);
    uint8_t combo = (sensor1Active ? 1 : 0) | (sensor2Active ? 2 : 0);

    GripType selectedGrip = GRIP_POWER;
    bool hold = true;
    uint8_t speed = 70;

    if (mode == MODE1) {
        switch (combo) {
            case 1: selectedGrip = GRIP_POWER; hold = true; speed = 90; break;
            case 2: selectedGrip = GRIP_CLOSED_PINCER; hold = false; speed = 70; break;
            case 3: selectedGrip = GRIP_OPEN_PINCER; hold = true; speed = 70; break;
            default: break;
        }
    } else {
        switch (combo) {
            case 1: selectedGrip = GRIP_POWER; hold = true; speed = 70; break;
            case 2: selectedGrip = GRIP_KEYBOARD; hold = true; speed = 70; break;
            case 3: selectedGrip = GRIP_CUP_HOLD; hold = true; speed = 50; break;
            default: break;
        }
    }

    if (combo != (prevSensor1Active?1:0) | (prevSensor2Active?2:0)) {
        if (gripActive && gripHoldActive) {
            releaseGrip();
        }
        if (combo != 0) {
            executeGrip(selectedGrip, hold, speed);
        } else {
            if (gripActive && !gripHoldActive) {
                releaseGrip();
            }
        }
    } else {
        if (combo == 0 && gripActive && !gripHoldActive) {
            releaseGrip();
        }
    }

    prevSensor1Active = sensor1Active;
    prevSensor2Active = sensor2Active;
}

void processEmergency() {
    if (emergencyExitPending) {
        currentState = STATE_MODE1;
        ledFlashMode = 0;
        emergencyExitPending = false;
        Serial.println("Выход из аварийного режима, переход в MODE1");
        // удалено: buttonLongPressHandled = false;
    }
}

void handleButton() {
    static bool lastButtonState = HIGH;
    static unsigned long debounceTime = 0;

    bool reading = digitalRead(BUTTON_PIN);
    if (reading != lastButtonState) {
        debounceTime = millis();
    }

    if ((millis() - debounceTime) > BUTTON_DEBOUNCE) {
        if (reading == LOW && !buttonPressed) {
            buttonPressed = true;
            buttonPressTime = millis();
        } else if (reading == HIGH && buttonPressed) {
            buttonPressed = false;
            buttonReleaseTime = millis();
            unsigned long pressDuration = buttonReleaseTime - buttonPressTime;

            if (pressDuration < SHORT_PRESS_MIN) {
                return;
            }

            if (pressDuration >= LONG_PRESS_MIN) {
                if (currentState != STATE_EMERGENCY) {
                    enterEmergency();
                } else {
                    emergencyExitPending = true;
                }
                return;
            }

            if (pressDuration >= SHORT_PRESS_MIN && pressDuration <= SHORT_PRESS_MAX) {
                unsigned long now = millis();
                if (singleClickPending && (now - lastSingleClickTime) <= DOUBLE_CLICK_INTERVAL) {
                    doubleClickDetected = true;
                    singleClickPending = false;
                } else {
                    singleClickPending = true;
                    lastSingleClickTime = now;
                    doubleClickDetected = false;
                }
            }
        }
    }

    lastButtonState = reading;

    if (singleClickPending && (millis() - lastSingleClickTime) > DOUBLE_CLICK_INTERVAL) {
        if (!doubleClickDetected) {
            handleSingleClick();
        }
        singleClickPending = false;
    }

    if (doubleClickDetected) {
        handleDoubleClick();
        doubleClickDetected = false;
        singleClickPending = false;
    }
}

void handleSingleClick() {
    if (currentState == STATE_ONE_SENSOR) {
        currentState = STATE_MODE1;
        ledFlashMode = 0;
        Serial.println("Переход в MODE1 (одинарный клик)");
    } else if (currentState == STATE_MODE1) {
        currentState = STATE_MODE2;
        ledFlashMode = 1;
        Serial.println("Переход в MODE2 (одинарный клик)");
    } else if (currentState == STATE_MODE2) {
        currentState = STATE_MODE1;
        ledFlashMode = 0;
        Serial.println("Переход в MODE1 (одинарный клик)");
    }
}

void handleDoubleClick() {
    if (currentState == STATE_ONE_SENSOR) {
        currentState = STATE_MODE2;
        ledFlashMode = 1;
        Serial.println("Переход в MODE2 (двойной клик)");
    } else if (currentState == STATE_MODE1) {
        currentState = STATE_MODE2;
        ledFlashMode = 1;
        Serial.println("Переход в MODE2 (двойной клик)");
    } else if (currentState == STATE_MODE2) {
        currentState = STATE_MODE1;
        ledFlashMode = 0;
        Serial.println("Переход в MODE1 (двойной клик)");
    }
}

void enterEmergency() {
    for (int i = 0; i < NUM_FINGERS; i++) {
        setFinger(i, ANGLE_MIN, 100);
    }
    currentState = STATE_EMERGENCY;
    ledFlashMode = 2;
    emergencyStartTime = millis();
    Serial.println("Аварийный режим активирован!");
}

bool isSensorActive(int pin) {
    int val = analogRead(pin);
    return val > SENSOR_THRESHOLD;
}

void updateLED() {
    unsigned long now = millis();
    switch (ledFlashMode) {
        case 0:
            digitalWrite(LED_PIN, LOW);
            break;
        case 1:
            digitalWrite(LED_PIN, HIGH);
            break;
        case 2:
            if (now - lastLEDToggleTime >= LED_FLASH_PERIOD / 2) {
                ledState = !ledState;
                digitalWrite(LED_PIN, ledState);
                lastLEDToggleTime = now;
            }
            break;
        case 3: {
            int cycleTime = now % LED_FLASH_PERIOD;
            if (cycleTime < LED_TWO_SHORT_ON) {
                digitalWrite(LED_PIN, HIGH);
            } else if (cycleTime < LED_TWO_SHORT_ON + LED_TWO_SHORT_OFF) {
                digitalWrite(LED_PIN, LOW);
            } else if (cycleTime < 2 * LED_TWO_SHORT_ON + LED_TWO_SHORT_OFF) {
                digitalWrite(LED_PIN, HIGH);
            } else {
                digitalWrite(LED_PIN, LOW);
            }
            break;
        }
    }
}
